<?php require 'functions.php';$products=load_data('products');$addresses=load_data('addresses');$carriers=load_data('carriers');$items=load_data('freights');if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$items=array_filter($items,fn($x)=>(int)$x['id']!==$id);save_data('freights',$items);redirect('freights.php','Frete excluído.');}if($_SERVER['REQUEST_METHOD']==='POST'){$pids=array_values(array_unique(array_map('intval',$_POST['products']??[])));$row=['id'=>next_id($items),'date'=>$_POST['date'],'origin'=>(int)$_POST['origin'],'destination'=>(int)$_POST['destination'],'carrier'=>(int)$_POST['carrier'],'products'=>$pids,'price'=>(float)$_POST['price'],'status'=>$_POST['status']];$items[]=$row;save_data('freights',$items);redirect('freights.php','Frete gerado com sucesso.');}$title='Fretes';require 'header.php';?>
<h2 class="page-title">Fretes</h2><div class="card p-4 mb-4"><h5>Gerar novo frete</h5><?php if(!$products||count($addresses)<2||!$carriers):?><div class="alert alert-warning">Cadastre pelo menos 1 produto, 2 endereços e 1 transportador antes de gerar o frete.</div><?php else:?><form method="post"><div class="row g-3"><div class="col-md-3"><label class="form-label">Data</label><input required type="date" class="form-control" name="date" value="<?=date('Y-m-d')?>"></div><div class="col-md-3"><label class="form-label">Origem</label><select required class="form-select" name="origin"><?php foreach($addresses as $x):?><option value="<?=$x['id']?>"><?=h($x['label'].' - '.$x['city'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Destino</label><select required class="form-select" name="destination"><?php foreach($addresses as $x):?><option value="<?=$x['id']?>"><?=h($x['label'].' - '.$x['city'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Transportador</label><select required class="form-select" name="carrier"><?php foreach($carriers as $x):?><option value="<?=$x['id']?>"><?=h($x['name'])?></option><?php endforeach;?></select></div></div><hr><label class="form-label">Produtos (um transportador pode levar vários)</label><div id="productRows"><div class="row g-2 product-row mb-2"><div class="col"><select required class="form-select" name="products[]"><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=h($x['name'].' - '.$x['sku'])?></option><?php endforeach;?></select></div><div class="col-auto"><button type="button" class="btn btn-outline-danger remove">Remover</button></div></div></div><button type="button" id="addProduct" class="btn btn-outline-primary btn-sm mb-3">+ Adicionar outro produto</button><div class="row g-3"><div class="col-md-4"><label class="form-label">Valor do frete (R$)</label><input required type="number" step="0.01" class="form-control" name="price"></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><option>Pendente</option><option>Em trânsito</option><option>Entregue</option></select></div><div class="col-md-4 d-flex align-items-end"><button class="btn btn-primary w-100">Gerar frete</button></div></div></form><?php endif;?></div>
<div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>#</th><th>Data</th><th>Transportador</th><th>Produtos</th><th>Status</th><th>Valor</th><th></th></tr></thead><tbody><?php foreach(array_reverse($items) as $x):$c=find_by_id($carriers,$x['carrier']);$names=[];foreach($x['products'] as $pid){$p=find_by_id($products,$pid);if($p)$names[]=$p['name'];}?><tr><td><?=$x['id']?></td><td><?=date('d/m/Y',strtotime($x['date']))?></td><td><?=h($c['name']??'N/D')?></td><td><?=h(implode(', ',$names))?></td><td><span class="badge text-bg-secondary"><?=h($x['status'])?></span></td><td>R$ <?=number_format($x['price'],2,',','.')?></td><td><a onclick="return confirm('Excluir frete?')" class="btn btn-sm btn-outline-danger" href="?delete=<?=$x['id']?>">Excluir</a></td></tr><?php endforeach;?></tbody></table></div></div>
<script>document.getElementById('addProduct')?.addEventListener('click',()=>{let first=document.querySelector('.product-row');let clone=first.cloneNode(true);document.getElementById('productRows').appendChild(clone)});document.getElementById('productRows')?.addEventListener('click',e=>{if(e.target.classList.contains('remove')&&document.querySelectorAll('.product-row').length>1)e.target.closest('.product-row').remove()});</script><?php require 'footer.php';?>
